import{p as e}from"./chunk-BF5idQyo.js";import{W as t,d as n,i as r}from"./chunk-BkML6sXq.js";var i="## @soroush.tech/design-system@1.0.0\n\nFirst stable release (#303) - the soroush.tech design system as a standalone\npackage: design tokens, consumer-owned theming, and the full component set,\nstyled through its own engine. The headless markdown editor/renderer ships\nseparately as its companion package, `@soroush.tech/markdown@1.0.0`.\n\n### Features\n\n- A token-driven, consumer-extensible `baseTheme` with the full component set:\n  layout & surfaces (View, Flex, Grid, Paper, Card, AppBar, Drawer), content &\n  data display (Typography, Link, Image, Icon, Table, Quote, Avatar, Skeleton,\n  Pagination), inputs & forms (Button, ButtonGroup, TextInput, NativeSelect,\n  Select, MenuItem, Checkbox, Radio, Switch, ToggleButton, Form, FormControl,\n  FormLabel, FormHelperText), feedback (CircularProgress, LinearProgress), and\n  overlay primitives (Modal, Popover, Portal, Backdrop, FocusTrap) - each on\n  its own subpath (`@soroush.tech/design-system/Button`, `.../Table/TableCell`, ...).\n- A self-owned styling API: `styled`, `css`, and `keyframes` from the root\n  barrel against the package's own `Theme` type - the styling engine is an\n  internal implementation detail, and nothing engine-specific leaks through\n  the public surface.\n  [docs](https://github.com/soroush-tech/core/blob/main/packages/design-system/docs/theming.md)\n- Three settled entry points: `.../theme` (`ThemeProvider`, `createTheme`,\n  `baseTheme`, `useTheme`, `useDefaultProps`, `withTheme`), the custom-CSS\n  layer at `.../style` (`useStyle`, `withStyles`, `StylesConsumer`), and raw\n  engine escape hatches at `.../engine` (`Global`, `globalStyles`,\n  `CacheProvider`, `styleCache` for SSR critical-CSS extraction - plus the\n  re-exported `@soroush.tech/styled-system` primitives).\n- Consumer-owned theming: `ThemeProvider` provides one theme (built-in dark by\n  default); `createTheme(base, overrides)` deep-merges sparse patches; every\n  scale is an open interface, extended via\n  `declare module '@soroush.tech/design-system/theme'` - palettes, tokens,\n  whole scales, and `theme.components` slots.\n  [docs](https://github.com/soroush-tech/core/blob/main/packages/design-system/docs/customization.md)\n- Overridable component defaults: literal fallbacks (`size = 'md'`,\n  `variant = 'outside'`, ...) resolve through `theme.defaults` / the provider's\n  `defaults` prop.\n- Per-component customization via `theme.components` - `defaultProps`, per-slot\n  `styleOverrides` with `{ theme, ownerState }` callbacks, and theme-contributed\n  `variants` (Button is the reference implementation; augmentable\n  `ButtonVariants`). Zero cost for themes that don't use it.\n- Test utilities under `.../utils/test` (`renderWithTheme`, stories helpers) for\n  consumers testing themed components.\n\n### Packaging\n\n- Dual ESM/CJS build via tsdown with a subpath export for every component\n  folder, including nested ones.\n- Peers are just `react` / `react-dom` `^19`; everything else ships as a\n  regular dependency - nothing to install alongside.\n- Supersedes the `0.1.0` preview release: the markdown suite (and `CodeBlock`)\n  now live in `@soroush.tech/markdown`, and the former `.../themes` / `.../colors`\n  subpaths are folded into `.../theme`.\n",a="## @soroush.tech/design-system@1.1.0\n\n### Features\n\n- `Sidebar` + `SidebarItem` - a collapsible vertical icon rail. Collapsed, it shows icon-only\n  items; open, each item's label appears next to its icon, rendered away from the anchored edge\n  (a right-anchored rail shows labels to the left of the icons), with the icon pinned so it holds\n  its position across the transition. Purely controlled via `isOpen` - the menu toggle lives with\n  the consumer (typically the app bar). Children compose freely (items, logos, footers);\n  `anchor`, `expandedWidth`, `collapsedWidth`, and any `Flex` prop (`bg`, ...) shape the rail.\n  Items are built on `Pressable` - real buttons carrying only the rail's own styling, with no\n  uppercase, bold weight, or letter-spacing inherited from the button family. They own their\n  selected fill and `aria-pressed`, take a `size` density token, accept custom `children`\n  for their open-state content, and stay accessible collapsed through `aria-label`s. The item\n  variant (`text` default, `outlined`, `plain`) can be set once on the rail - `Sidebar`'s\n  `variant` flows to every item through context, with an item's own `variant` winning. The rail is a labeled `<nav>` landmark,\n  animates its width honoring `prefers-reduced-motion`, and registers the `Sidebar` and\n  `SidebarItem` theme slots.\n  With `hasPanel`, the rail gains a second column and the selected item's `children` render there\n  instead of inside its row - an icon rail beside a detail panel, sized by `panelWidth`. The\n  column appears only when the selected item has children, so nothing selected leaves no empty\n  gap; it sits on the rail's inner side following `anchor`, and is independent of `isOpen`, so a\n  collapsed icons-only rail can sit beside an open panel. The panel is a `<section>` named by the\n  item's `label`, and that item becomes a disclosure carrying `aria-expanded` and `aria-controls`.\n  Selection stays the consumer's - the rail only decides where the children go. Off by default,\n  so `children` keep rendering inline in the row as before.\n- `Pressable` - an unstyled clickable surface: button semantics (keyboard activation, focus ring,\n  disabled state) with none of a button's looks. It carries no padding, margin, border,\n  background, or font of its own, so it wraps arbitrary content without shifting it - the\n  primitive to use instead of an `onClick` on a `div`, which no keyboard or screen-reader user\n  can reach. It renders a `div` by default, since a `<button>` may not legally contain a link,\n  another button, or block-level markup; that div is given `role=\"button\"`, a tab stop,\n  `Enter`/`Space` activation (Space suppressed on keydown so the page never scrolls, fired on\n  keyup), and `aria-disabled`. `as=\"button\"` opts into a native button when the content is\n  phrasing-only, `href` renders an anchor, and both skip the shim. `feedback` picks what happens\n  while it is held: `none` (default) leaves the content alone, `opacity` fades it to\n  `activeOpacity`, and `highlight` tints the surface with `color` at 12.5% opacity. Feedback is\n  press-only, so hover styling stays with the consumer. Its text is never selectable, so a drag\n  or double-click presses rather than highlighting, as on a native button. Accepts the `space`,\n  `layout`, `border`,\n  and `typography` props, and registers the `Pressable` theme slot with themeable\n  `feedback`/`color`/`activeOpacity` defaults.\n- `Icon` - three new registry entries: `folder`, `history`, and `edit_note`.\n\n### Changes\n\n- `gap`, `rowGap`, `columnGap` and `aspectRatio` now come from `View` for every primitive built on\n  it, resolved by `@soroush.tech/styled-system` 5.8.0's own `space` and `layout` parsers instead of\n  per-component `system()` mappings. `Flex`, `Grid`, `Button`, `Link` and `Paper` dropped that\n  hand-wiring - same CSS, same theme scale, same DOM filtering, and the props now accept responsive\n  arrays everywhere. `Flex`'s and `Grid`'s `GapToken` exports are unchanged.\n  ([#314](https://github.com/soroush-tech/core/issues/314))\n\n### Breaking\n\n- **`Link`'s `gap` narrows** from `number | string` to the `theme.space` token union, matching\n  every other component's `gap`. Token values (`gap={2}`, `gap=\"auto\"`) are unaffected; raw CSS\n  values (e.g. `gap=\"8px\"`) no longer type-check. Shipped in a minor deliberately: the prop reached\n  raw CSS only because `Link` hand-wired its own `gap` parser, which is the inconsistency this\n  release removes, and no consumer in this repo passes one. Replace a raw value with the nearest\n  `theme.space` token, or set `gap` through `style`/`css` if you need an off-scale length.\n  ([#314](https://github.com/soroush-tech/core/issues/314))\n",o="## @soroush.tech/design-system@1.2.0\n\nMaintenance release - dependency refresh only. No new components, no API or behavior changes.\n([#280](https://github.com/soroush-tech/core/pull/280))\n\n### Packaging\n\n- **`react` and `react-dom` peer floors raised `^19.0.0` → `^19.2.8`.** Still React 19 only -\n  the range narrows to the patch line this release is built and tested against. Consumers on an\n  earlier React 19 should upgrade before installing.\n- `@soroush.tech/styled-system` dependency floor moves to `^5.8.1` with that package's own\n  maintenance release. `@emotion/*` dependencies are unchanged.\n- Dev-dependency bumps: `@storybook/react-vite` `^10.5.0` → `^10.5.6`, `@testing-library/jest-dom`\n  `^6.9.1` → `^7.0.0`, `@types/node` `^26.1.1` → `^26.1.2`, `@types/react` `^19.2.17` →\n  `^19.2.18`, `@types/react-dom` `^19.2.3` → `^19.2.4`, `eslint` `^10.7.0` → `^10.8.0`,\n  `eslint-plugin-storybook` `^10.5.0` → `^10.5.6`, `globals` `^17.7.0` → `^17.9.0`, `playwright`\n  `^1.61.1` → `^1.62.1`, `react`/`react-dom` `^19.2.7` → `^19.2.8`, `storybook` `^10.5.0` →\n  `^10.5.6`, `tsdown` `^0.22.7` → `^0.22.14`.\n- `jsdom` stays on `^29.1.1`. jsdom 30 absolutizes relative lengths in `getComputedStyle`\n  (`2rem` resolves to `32px`), which breaks the `toHaveStyle` assertions this package's tests\n  write in `rem`/`em`; the upgrade is held in `renovate.json` until those assertions stop\n  comparing against computed style. Test-only - it does not affect the published package.\n",s="## @soroush.tech/design-system@1.3.0\n\nCode-quality release driven by static analysis\n([#333](https://github.com/soroush-tech/core/pull/333) follow-up): no new components, no\nbehavior changes.\n\n### Changed\n\n- `TextInput` picks its input element (`input` / `textarea` / auto-resizing `textarea`) through\n  a plain statement instead of a nested ternary. Rendered output is identical.\n\n### Breaking\n\n- **`ariaHidden(element, hide)` is replaced by `hideFromAria(element)` and\n  `exposeToAria(element)`** on the Modal subpath. The boolean-selector helper was a leaked\n  internal of `ModalManager` - no consumer in this repo imports it, and modal behavior is\n  unchanged. Shipped in a minor deliberately, following the precedent of the styled-system\n  `themeGet` root-export removal: the export only existed by accident. Migrate\n  `ariaHidden(el, true)` → `hideFromAria(el)` and `ariaHidden(el, false)` → `exposeToAria(el)`.\n",c="## @soroush.tech/design-system@1.3.1\n\nRestores the style props on the published component types - they resolved to `any` for consumers\non 1.2.0 and 1.3.0 - and refreshes dependencies.\n([#335](https://github.com/soroush-tech/core/issues/335))\n\n### Fixed\n\n- **Style props are back on every component's published types.** `TypographyProps`, `ImageProps`,\n  `TextInputProps` and the rest inherit their space / layout / typography / flexbox / border /\n  background / position / grid prop groups from `@soroush.tech/styled-system`, and the components\n  used to reach for those types through this package's own barrel, which passes them on with\n  `export *`. The d.ts bundler flattens that barrel into a `declare namespace`, which cannot carry\n  an `export *`, so the names were referenced but never declared in the emitted types. Under the\n  `skipLibCheck` consumers compile with, those dangling references degraded to `any` rather than\n  erroring: every style prop disappeared (`<Typography mt={2}>`, `<Image width=\"100%\">`), and\n  `TextInput`'s `Pick<LayoutProps, 'width' | 'minWidth' | 'maxWidth'>` turned those three into\n  **required** props. Components now import the types straight from\n  `@soroush.tech/styled-system`, so nothing routes through that namespace. The emitted JavaScript\n  and the runtime API are unchanged - this release moves types only.\n\n### Packaging\n\n- Dev-dependency bumps: `@storybook/react-vite` `^10.5.6` → `^10.5.7`, `eslint-plugin-storybook`\n  `^10.5.6` → `^10.5.7`, `storybook` `^10.5.6` → `^10.5.7`, `eslint` `^10.8.0` → `^10.8.1`,\n  `@types/node` `^26.1.2` → `^26.2.0`.\n- Repo-wide dependency overrides clear the vulnerable transitives the lockfile resolved for this\n  package's dev tree (`webpack` forced to `>=5`, `eslint-plugin-import` to `>=2.32.0`, plus\n  in-range patches for `brace-expansion`, `dompurify`, `js-yaml`, and `postcss`).\n- No runtime, peer, or optional-peer dependency changes.\n",l="## @soroush.tech/design-system@1.3.2\n\nMaintenance release - the package gained a Storybook of its own. No public API, behavior, or\nemitted-output changes.\n\n### Packaging\n\n- `storybook` no longer delegates to the site's Storybook: the package has its own config in\n  [`.storybook/`](https://github.com/soroush-tech/core/tree/main/packages/design-system/.storybook),\n  serving only this package's stories against the shipped `baseTheme` on port 6007 - the component\n  library is now viewable without the site checked out. `build:storybook` and `test:storybook`\n  scripts were added alongside it; the latter runs every story's play function and a11y check.\n- New dev dependencies: `@storybook/addon-a11y` `^10.5.8`, `@storybook/addon-docs` `^10.5.8`,\n  `@storybook/addon-vitest` `^10.5.8`.\n- Dev-dependency bumps: `@storybook/react-vite` and `storybook` `^10.5.7` → `^10.5.8`,\n  `@testing-library/jest-dom` `^7.0.0` → `^7.0.1`.\n- `jsdom` stays on `^29.1.1`, held repo-wide in\n  [`renovate.json`](https://github.com/soroush-tech/core/blob/main/renovate.json): jsdom 30\n  absolutises relative lengths in `getComputedStyle`, so `2rem` resolves to `32px` and\n  `-0.025em` to `-0.4px`, and every `toHaveStyle` assertion written in rem or em fails.\n- No runtime, peer, or optional-peer dependency changes. The `files: [\"dist\"]` allowlist is\n  unchanged, so `.storybook/` is not part of the published tarball.\n",u=`## @soroush.tech/design-system@1.3.3

Maintenance release. One rendered string changes; no API changes.

### Changed

- \`TablePagination\`'s default displayed-rows label now reads \`1-10 of 57\` with a hyphen, where it
  used an en dash. \`labelDisplayedRows\` is a prop: pass your own to render it any other way.

No other component's rendered output changed.
`,d=`## @soroush.tech/design-system@1.3.4

Documentation only. No code and no API changes - the published bundle is identical to 1.3.3.

### Added

- Every component now owns its documentation page: \`<Name>.mdx\` sits beside the component's
  \`README.md\` and drives that component's page on docs.soroush.tech. The page renders the
  README's intro followed by every story in \`<Name>.stories.tsx\` as a live, editable demo.
- The page is required - a component without one fails the docs build.
- The README now explains how to point an AI assistant at this library: the hosted MCP server,
  the same server locally over stdio, and the Claude Code plugin that wraps it.
- \`docs/consumer/\` carries the consumer-facing setup guide, the layout-kit patterns, and
  copyable \`theme.ts\` / \`providers.tsx\` starters. The MCP server serves these to AI tools; they
  are repo files, not part of the npm tarball.
`,f="## @soroush.tech/markdown@1.0.0\n\nFirst stable release - the headless markdown editor + renderer, extracted from\n`@soroush.tech/design-system` into its own package. Ships alongside its\ncompanion `@soroush.tech/design-system@1.0.0`, which it builds on (peer) for\nprimitives, the `styled` engine, and theming. `0.1.0` was never published;\nthis is the package's first appearance on npm.\n\n### Features\n\n- Headless, composable markdown parts importable from the barrel: `Control` (state provider),\n  `Toolbar` (formatting buttons, heading/code selects, table picker), `Editor` (source textarea\n  with Tab-to-indent, selection, and caret restore), and `Preview` (a standalone renderer of\n  markdown to design-system primitives, built on `react-markdown`, `remark-gfm`, and\n  `rehype-highlight`).\n- `CodeBlock` - the syntax-highlighted code renderer with a hover-revealed copy control,\n  usable standalone and as `Preview`'s code element. Highlight tokens come from\n  `theme.syntax` (`syntaxDark` / `syntaxLight` presets included).\n- `Mermaid` - fenced ` ```mermaid ` blocks render as diagrams in `Preview` (#282). mermaid is\n  loaded lazily via dynamic import, so documents without diagrams never pay for it; per-theme\n  styling goes through `theme.mermaid` (`MermaidThemeVariables`, merged over the defaults).\n- Per-component theming: the roots register the `MarkdownEditor`, `MarkdownPreview`,\n  `MarkdownToolbar`, and `CodeBlock` slots on `@soroush.tech/design-system/theme`'s\n  `ThemeComponents`, so consumers customize defaults and styling through design-system's\n  `createTheme` / `theme.components`; `theme.syntax` and `theme.mermaid` extend the same\n  augmentation surface.\n\n### Packaging\n\n- Peers: `@soroush.tech/design-system` and `react` / `react-dom` `^19`.\n- `react-markdown`, `remark-gfm`, `rehype-highlight`, and `mermaid` are regular\n  dependencies - consumers install nothing beyond the peers.\n",p="## @soroush.tech/markdown@1.1.0\n\n### Features\n\n- `LiveEdit` - a preview you write on directly. The document renders exactly like `Preview`,\n  split into top-level blocks, and every block is `contentEditable`: type straight into the\n  styled output, no textarea. Each input serializes the edited block's DOM back to markdown\n  (`rehype-parse` → `rehype-remark` → `remark-stringify`, GFM-aware) and splices it into\n  `value`, so `onChange` fires live and untouched blocks keep their exact source. Blur or\n  Escape re-splits the document; fenced code keeps its language; ` ```mermaid ` blocks stay\n  read-only (a diagram has no text to edit in place). Works standalone (`value`/`onChange`) or\n  composed inside a `Control`, and registers the `MarkdownLiveEdit` slot (`root` / `block`) on\n  `theme.components` for per-theme styling.\n\n- `Editor` - new `maxRows` prop (forwarded to the underlying auto-grow textarea): the source\n  field stops growing at that height and scrolls internally, keeping its border box visible\n  inside height-bound panes.\n\n### Fixes\n\n- `Preview` - fenced-code `code` elements keep their `language-*` class on the DOM (previously\n  dropped by the styled wrapper). This is what lets `LiveEdit` preserve a fence's language when\n  the block is edited in place, and it makes the rendered language targetable by consumer CSS.\n\n### Packaging\n\n- New dependencies for the DOM→markdown pipeline: `unified`, `rehype-parse`, `rehype-remark`,\n  and `remark-stringify` (all from the unified ecosystem the package already builds on).\n",m="## @soroush.tech/markdown@1.2.0\n\nMaintenance release - dependency refresh only. No new components, no API or behavior changes.\n([#280](https://github.com/soroush-tech/core/pull/280))\n\n### Packaging\n\n- **`mermaid` dependency floor raised `^11.4.0` → `^11.16.1`** - same major, backward compatible.\n  It stays lazily imported, so the diagram bundle is still only fetched when a `mermaid` code\n  fence renders.\n- **`react` and `react-dom` peer floors raised `^19.0.0` → `^19.2.8`.** Still React 19 only -\n  the range narrows to the patch line this release is built and tested against.\n- **`@soroush.tech/design-system` peer floor moves to `^1.2.0`** with that package's own\n  maintenance release, whose React peer floors move in step.\n- Dev-dependency bumps: `@storybook/react-vite` `^10.5.0` → `^10.5.6`, `@testing-library/jest-dom`\n  `^6.9.1` → `^7.0.0`, `@types/node` `^26.1.1` → `^26.1.2`, `@types/react` `^19.2.17` →\n  `^19.2.18`, `@types/react-dom` `^19.2.3` → `^19.2.4`, `eslint` `^10.7.0` → `^10.8.0`,\n  `eslint-plugin-storybook` `^10.5.0` → `^10.5.6`, `globals` `^17.7.0` → `^17.9.0`,\n  `react`/`react-dom` `^19.2.7` → `^19.2.8`, `storybook` `^10.5.0` → `^10.5.6`, `tsdown`\n  `^0.22.7` → `^0.22.14`. `jsdom` stays on `^29.1.1` - held repo-wide in `renovate.json`, see\n  the design-system 1.2.0 notes.\n",h="## @soroush.tech/markdown@1.2.1\n\nMaintenance release - build tooling and a dependency refresh. No public API, behavior, or\nemitted-output changes.\n([#328](https://github.com/soroush-tech/core/issues/328))\n\n### Packaging\n\n- The workspace replaced ESLint with [oxlint](https://oxc.rs). This package's `eslint.config.js`\n  became an `.oxlintrc.json`, and its `lint` script now runs `oxlint --deny-warnings`; the enforced\n  rule set is unchanged, including every `react-hooks` rule. Dev-dependency change only - `eslint`\n  and its plugins out, `oxlint` in. No runtime or peer dependency changes, and the published\n  tarball is unaffected.\n- `typescript` moves to `~7.0.2`. It is a dev dependency here, used to typecheck and emit; the\n  emitted output is unchanged.\n- Dev-dependency bumps: `@storybook/react-vite` and `storybook` `^10.5.6` → `^10.5.8`,\n  `@testing-library/jest-dom` `^7.0.0` → `^7.0.1`. No runtime or peer dependency changes, and\n  the `@soroush.tech/design-system` peer floor is unchanged.\n- `jsdom` stays on `^29.1.1`, held repo-wide in\n  [`renovate.json`](https://github.com/soroush-tech/core/blob/main/renovate.json) - see the\n  design-system notes for the reason.\n",g=`## @soroush.tech/markdown@1.2.2

Maintenance release. Two default placeholders change; no API changes.

### Changed

- \`Markdown.Editor\`'s default placeholder is \`Write your article in Markdown...\` and \`LiveEdit\`'s
  is \`Click to start writing...\`, each ending in three periods rather than an ellipsis character.
  Both are props: pass your own \`placeholder\` to keep any other text.

No rendered markdown output, theme slot, or mermaid behavior changed.
`,_="## @soroush.tech/mcp@0.1.0\n\nFirst release. An MCP server that gives AI coding tools first-class access to the\ndesign system: the component inventory, every component README, and the theme token\ncontract, all generated from this repo's own sources at build time.\n\n### Added\n\n- Six tools: `list_components`, `get_component`, `get_tokens`, `list_docs`, `get_doc`,\n  and `search_docs`. `get_component` serves a component's README, optionally sliced\n  into `intro`, `api` (its props with token values and defaults), or `examples`.\n- Two transports from one implementation. Run it locally over stdio with\n  `npx -y @soroush.tech/mcp`, or connect to the hosted server:\n\n  ```sh\n  claude mcp add --transport http soroush https://mcp.soroush.tech/mcp\n  ```\n\n- Content generated from the repo rather than hand-maintained: component READMEs come\n  from `packages/*/src/*/README.md` through the same registry and splitter the docs site\n  uses, and the token contract is serialized from the live `baseTheme`, so a new scale\n  appears with no extra step.\n",v='# @soroush.tech/styled-system v5.2.0\n\nThe first release of our ground-up rewrite of\n[styled-system](https://github.com/jxnblk/styled-system) - a maintained,\n**first-class-TypeScript** implementation of responsive, theme-aware style props for\nCSS-in-JS.\n\nIt\'s a **drop-in replacement** for the `styled-system` v5 runtime: the root export surface\nmatches upstream verbatim, so existing code keeps working, while everything underneath is new.\n\n## Highlights\n\n- **Complete TypeScript rewrite** - the entire style engine (`system`, `compose`,\n  `createParser`, `createStyleFunction`, `get`) was rebuilt from scratch with first-class\n  types. Every style function carries its own typed prop interface (`SpaceProps`, `ColorProps`,\n  `LayoutProps`, ...).\n- **Ships its own types** - no more `@types/styled-system`. Types are theme-scale-aware and\n  bundled in the package.\n- **Dual ESM + CJS build** with per-category subpath exports (`/space`, `/color`, `/layout`,\n  `/css`, `/theme-get`, `/props`, `/should-forward-prop`, ...) mirroring the original\n  `@styled-system/*` packages.\n- **Tree-shakeable** (`"sideEffects": false`), zero runtime CSS-in-JS dependency - bring your\n  own Emotion or styled-components.\n- **100% test coverage**, MIT licensed.\n\n## ⚠️ Breaking change: `propTypes` dropped\n\nStyle functions **no longer expose a `propTypes` property**, and there is no `prop-types`\ncompanion package. The old `@styled-system/prop-types` is out of scope for this rewrite, and\nReact 19 removed `propTypes` for function components entirely.\n\n**Migrate by using TypeScript for prop typing** - each style function already provides a typed\nprop interface, so you get compile-time checking instead of runtime `propTypes`:\n\n```ts\nimport { space, type SpaceProps } from \'@soroush.tech/styled-system\'\n```\n\nSee the [TypeScript guide](https://github.com/soroush-tech/core/tree/main/packages/styled-system/docs/typescript.md).\n\n## Install\n\n```sh\nnpm install @soroush.tech/styled-system\n```\n\nExisting `styled-system` users can swap with no code changes via a package-manager alias:\n\n```jsonc\n"dependencies": {\n  "styled-system": "npm:@soroush.tech/styled-system@^5"\n}\n```\n\n`@emotion/is-prop-valid` (`^1.4.0`) is a peer dependency, needed only if you import the\n`should-forward-prop` subpath.\n',y="## @soroush.tech/styled-system@5.3.0\n\nCloses the remaining gaps for a true drop-in replacement of `styled-system@5` +\n`@types/styled-system` (#213).\n\n### Added\n\n- **Per-property prop types.** Every atomic interface from `@types/styled-system` is now\n  exported (`WidthProps`, `HeightProps`, `OverflowProps`, `TopProps`, `ZIndexProps`,\n  `AlignItemsProps`, `JustifyContentProps`, `FlexProps`, `FontSizeProps`, `FontWeightProps`,\n  `LineHeightProps`, `TextAlignProps`, `TextColorProps`, `BackgroundColorProps`, `OpacityProps`,\n  `BorderWidthProps`, `BorderStyleProps`, `BorderColorProps`, `BorderRadiusProps`,\n  `BorderTop/Right/Bottom/LeftProps`, `BoxShadowProps`, `TextShadowProps`, `TextStyleProps`, and\n  the full `Grid*` and `Background*` families).\n- Each grouped interface (`LayoutProps`, `FlexboxProps`, `BorderProps`, ...) now composes its\n  atomic interfaces via `extends`, matching upstream's structure.\n- All types are re-exported from their matching subpath (`./layout`, `./position`, `./border`,\n  ...) as well as the main entry.\n- `themeGet` is now also available as a named export from the main entry:\n  `import { themeGet } from '@soroush.tech/styled-system'`.\n\n### Changed\n\n- **`Transform` is no longer `unknown`.** It now matches `@styled-system/core`'s\n  `(value: any, scale?: any) => any`, so consumer transforms like\n  `(val) => MAP[val] ?? MAP.center` compile without casts (no more TS2538).\n\n### Notes\n\n- `boxShadow`, `textShadow`, and `fontWeight` remain intentionally widened over upstream to also\n  accept `string` theme keys.\n- No runtime behavior changes; fully backward compatible.\n- Still deferred: a `@styled-system/prop-types` equivalent (issue #213 §3).\n",b="## @soroush.tech/styled-system@5.4.0\n\nFinishes drop-in parity with the `styled-system@5` ecosystem - head-to-head is now 16/16 with\nthe original packages. Builds on 5.3.0 (per-property prop types + `Transform` fix).\n\n### Added\n\n- **`./prop-types` subpath** mirroring `@styled-system/prop-types`: `propType`,\n  `createPropTypes`, and a default per-group map (`space, color, layout, typography, flexbox,\nborder, background, position, grid, shadow, buttonStyle, textStyle, colorStyle`) built from\n  each parser's `propNames`. Spread it onto a component:\n  `Box.propTypes = { ...propTypes.space, ...propTypes.color }`.\n- **`themeGet` as the package-root default export** (in addition to the named export added in\n  5.3.0). A package-manager alias can only bind `@styled-system/theme-get` → the package root,\n  so `import themeGet from '@styled-system/theme-get'` previously resolved to `undefined`; both\n  `import { themeGet }` and `import themeGet` now work under the alias.\n\n### Notes\n\n- New **optional** peer dependency `prop-types` (`^15.8.1`) - required only if you import\n  `./prop-types`. It stays external in the build (~1.6 KB ESM), and the public types use a\n  structural validator so consumers aren't forced to install `@types/prop-types`.\n- No runtime behavior change to existing exports; fully backward compatible.\n",x="## @soroush.tech/styled-system@5.5.0\n\nType-resolution fix for classic-`node` consumers, plus a parity correction to the package root.\nRecommended upgrade from 5.4.0 (now deprecated).\n\n### Fixed\n\n- **Subpath types now resolve under classic `moduleResolution: \"node\"` (node10).** Classic\n  resolution doesn't read a package's `exports` map, so `tsc` couldn't find types for\n  `styled-system/theme-get`, `styled-system/prop-types`, `styled-system/core`, etc. (`TS2307`),\n  even though runtime worked. Added a `typesVersions` map (in `publishConfig`) pointing every\n  subpath at its `.d.cts` - the mechanism classic `node` honors. No consumer changes required\n  (no `paths`, no `declare module`, no `moduleResolution` change). Modern resolution\n  (`node16`/`nodenext`/`bundler`) continues to resolve via `exports`.\n\n### Removed (parity)\n\n- **The package root no longer exports `themeGet` or a `default`.** The original `styled-system`\n  main package exports neither - both only ever lived in the standalone\n  `@styled-system/theme-get`. `themeGet` remains available (named + default) from the\n  `./theme-get` subpath: `import themeGet from '@soroush.tech/styled-system/theme-get'`.\n\n### Docs\n\n- Drop-in guidance now aliases the **main** `styled-system` name and imports satellites as\n  subpaths off it - `import themeGet from 'styled-system/theme-get'` - which resolves through\n  this package's `exports` (and `typesVersions` for node10).\n\n### Upgrade notes\n\n- From 5.4.0: drop-in. If you imported `themeGet` from the package root (5.3.0/5.4.0 only),\n  switch to `@soroush.tech/styled-system/theme-get`.\n- 5.4.0 is deprecated (root default divergence + the node10 type gap fixed here).\n",S="## @soroush.tech/styled-system@5.6.0\n\nCompletes props-facing type parity with `@types/styled-system` - closes the drop-in gaps found\nmigrating a real styled-system v5 monorepo (#215). Recommended upgrade from 5.5.0.\n\n### Fixed\n\n- **`themeGet` matches `@types/styled-system__theme-get` verbatim** -\n  `(path: string | Array<string | number>, fallback?: any) => (props: any) => any`. No more\n  `unknown` returns (TS2339 on destructuring) and no more rejecting component prop interfaces\n  (TS2345). Array paths now also resolve as nested lookups (`themeGet(['colors','primary'])`),\n  fixing a latent bug the upstream runtime never handled.\n- **Public type surface loosened to `any` to match upstream** - `Props`/`Theme` index\n  signatures, `Transform`/`StyleFn` params, `StyleObject`, `ConfigStyle.defaultScale`,\n  `ThemeValue`. Strict `unknown`/`Props` no longer breaks CSS-in-JS interpolation or arbitrary\n  component props.\n- **`boxShadow` / `textShadow` / `fontWeight` accept `string | number`** - resolves against both\n  object-keyed (`{ sm, md }`) and array-indexed (`[...]`) theme scales; restores array-index\n  support that had been dropped.\n\n### Added\n\n- **Upstream type-name aliases** for drop-in imports: `styleFn`, `Config`, `ConfigFunction`,\n  `VariantArgs`, `LowLevelStyleFunctionArguments`.\n\n### Changed\n\n- **`@emotion/is-prop-valid` is now an optional peer dependency** (`peerDependenciesMeta`) - no\n  more `missing peer` warning for consumers who don't use the `./should-forward-prop` subpath.\n- `css` exports `CSSObject` (was `CssObject`) to match `@styled-system/css`'s actual name.\n\n### Upgrade\n\n- From 5.5.0: drop-in, no code changes. This makes the scoped-package migration described in\n  #215 package.json-only.\n- 5.5.0 and earlier are deprecated (see notes).\n",C=`## @soroush.tech/styled-system@5.6.1

### Changes

- Raise \`csstype\` runtime dependency floor \`^3.1.3\` → \`^3.2.3\` (newer CSS property typings).
- Repository moved to \`soroush-tech/core\`.

No public type or API changes.
`,w="## @soroush.tech/styled-system@5.7.0\n\nExtend the `typography` style function with seven text-styling props the original\nstyled-system never shipped - first-class, theme-aware props alongside `textAlign` and\n`fontStyle`. Additive and backward-compatible. (#258, #259)\n\n### Added\n\n- **`textTransform`**, **`textAlignLast`**, **`textDecoration`**, **`textDecorationLine`**,\n  **`textDecorationStyle`**, **`textDecorationThickness`** - raw CSS pass-through props, each\n  exported standalone and folded into `TypographyProps`; auto-covered by `should-forward-prop`.\n- **`textDecorationColor`** - resolves against the `colors` theme scale (like `borderColor`),\n  in both the parser and the `css()` object-notation path.\n- Docs: [Typography props reference](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/api.md#typography)\n  · [migration guide](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/guides/migrating.md).\n\n### Upgrade\n\n- From 5.6.x: drop-in, no code changes.\n\n### Packaging\n\n- No runtime or peer dependency changes (dev-only tooling bumps).\n",T=`## @soroush.tech/styled-system@5.7.1

Maintenance release - dependency refresh only. No public API or behavior changes.

### Packaging

- Dev-dependency bumps: \`tsdown\` \`^0.22.4\` → \`^0.22.7\`. No runtime or peer dependency
  changes.
`,E="## @soroush.tech/styled-system@5.8.0\n\nScale flex and grid gaps on `space`, add `aspectRatio` to `layout`, and add `whiteSpace` and\n`textOverflow` to `typography` - six props the original styled-system never shipped. Additive and\nbackward-compatible.\n([#313](https://github.com/soroush-tech/core/issues/313))\n\n### Added\n\n- **`gap`**, **`rowGap`**, **`columnGap`** - resolve against `theme.space`, the same scale (and\n  default scale) as margins and paddings, and compose into `space` alongside `margin` and\n  `padding`. Upstream only ever scaled the grid-prefixed `gridGap`/`gridRowGap`/`gridColumnGap`,\n  so flex gaps had to be hand-wired through `system()`; that custom mapping can go. Typed via\n  **`GapProps`**/**`RowGapProps`**/**`ColumnGapProps`**, composed into `SpaceProps`. The `gap`\n  parser is also exported standalone, alongside `margin` and `padding`.\n- **`aspectRatio`** - maps straight to CSS `aspect-ratio` (no theme scale). Upstream's last\n  release predates the property, so this too was hand-wired; that mapping can go as well. Typed\n  via **`AspectRatioProps`**, composed into `LayoutProps` and re-exported from the `/layout`\n  subpath.\n- **`whiteSpace`** and **`textOverflow`** - map straight to CSS `white-space` and `text-overflow`\n  (no theme scale). Together with `overflow` from `layout` they make text truncation expressible in\n  props alone, instead of dropping into raw CSS for the one declaration the parser was missing.\n  Typed via **`WhiteSpaceProps`**/**`TextOverflowProps`**, composed into `TypographyProps` and\n  re-exported from the `/typography` subpath, with both parsers also exported standalone alongside\n  `textAlign` and `textTransform`.\n- All support responsive array and breakpoint-object values, and are filtered from the DOM\n  automatically - none needs adding to a `shouldForwardProp` blocklist, since `props` derives\n  from `all.propNames`.\n- Docs: [Space props reference](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/api.md#space)\n  · [Layout props reference](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/api.md#layout)\n  · [Typography props reference](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/api.md#typography)\n  · [prop/scale table](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/table.md)\n  · [theme specification](https://github.com/soroush-tech/core/blob/main/packages/styled-system/docs/theme-specification.md#key-reference).\n\n### Upgrade\n\n- From 5.7.x: drop-in, no code changes. Components that hand-wired `gap` or `aspectRatio`\n  through `system()` can delete that mapping and inherit the props from `space`/`layout`.\n\n### Packaging\n\n- No runtime or peer dependency changes.\n",D="## @soroush.tech/styled-system@5.8.1\n\nMaintenance release - dependency refresh only. No public API or behavior changes.\n([#280](https://github.com/soroush-tech/core/pull/280))\n\n### Packaging\n\n- Dev-dependency bumps: `eslint` `^10.7.0` → `^10.8.0`, `globals` `^17.7.0` → `^17.9.0`,\n  `tsdown` `^0.22.7` → `^0.22.14`. No runtime or peer dependency changes.\n",O=`## @soroush.tech/styled-system@5.8.2

Maintenance release - build tooling only. No public API, behavior, or type changes.
([#328](https://github.com/soroush-tech/core/issues/328))

### Packaging

- The workspace moved its formatter from Prettier to \`oxfmt\`, which wraps multi-line union types
  onto leading-pipe lines. That reformatted the \`ObjectOrArray\` declaration in \`src/types.ts\`;
  the type it describes is unchanged. No source, runtime, peer, or dev dependency changes.
- \`typescript\` moves to \`~7.0.2\`. It is a dev dependency here, used to typecheck and emit; the
  emitted output is unchanged.
`,k=`## @soroush.tech/styled-system@5.8.3

Maintenance release. No public API, behavior, or emitted-output changes - comments and docs only.
No scale, prop, or generated style changed.
`,A="## @soroush.tech/ui-spec@0.1.0\n\nFirst release. The generative-UI spec for the design system: one JSON shape an agent writes and\na tool validates, built on A2UI v1.0 with that protocol left unchanged.\n\n### Added\n\n- **`composeCatalog`** - builds an A2UI v1.0 catalog from an app's components, with the core\n  added: the `When` component and eight functions (`setValue`, `lookup`, `sumField`, `divide`,\n  `round`, `ceil`, `max`, `select`).\n  [docs](https://github.com/soroush-tech/design-system/blob/main/packages/ui-spec/README.md#catalogs)\n- **`When`** - a component that renders one child chosen by a value. A2UI v1.0 has no\n  conditional rendering, so this is how a surface shows a skeleton, an error and the content.\n  [docs](https://github.com/soroush-tech/design-system/blob/main/packages/ui-spec/README.md#showing-a-skeleton-an-error-and-the-content)\n- **`applyTheme`** - specializes a catalog for one app's theme, so a token key or a Button\n  variant the app added through its theme is accepted.\n  [docs](https://github.com/soroush-tech/design-system/blob/main/packages/ui-spec/README.md#props-that-come-from-the-theme)\n- **`behaviorSchema`** - the JSON Schema of a behavior document, version 0.1: page params,\n  queries and mutations, derived values, triggers and the document head.\n  [docs](https://github.com/soroush-tech/design-system/blob/main/packages/ui-spec/README.md#the-behavior-document)\n- **`validateCatalog`**, **`validateSurface`**, **`validateBehavior`** - validators that return\n  findings as data and never throw. Each finding carries a code from a closed set, a JSON\n  Pointer into the document, and a message.\n  [docs](https://github.com/soroush-tech/design-system/blob/main/packages/ui-spec/README.md#validating)\n\n### Packaging\n\n- Depends on `ajv` `^8.18.0` and `ajv-formats` `^3.0.1`. The engine was chosen by running the\n  156 conformance cases of the A2UI specification: `ajv` agrees with all of them.\n- Bundles the A2UI v1.0 JSON schemas and basic catalog, unmodified, from commit `46ecc2d0` of\n  the A2UI repository. They are licensed under the Apache License, Version 2.0; the license and\n  a note of the source ship in `vendor/a2ui/v1_0/`.\n",j=(e,t)=>{let n=e=>e.split(`.`).map(Number),[r,i]=[n(e),n(t)];for(let e=0;e<3;e+=1)if(r[e]!==i[e])return r[e]-i[e];return 0},M=Object.assign({"../../packages/design-system/release-notes/1.0.0.md":i,"../../packages/design-system/release-notes/1.1.0.md":a,"../../packages/design-system/release-notes/1.2.0.md":o,"../../packages/design-system/release-notes/1.3.0.md":s,"../../packages/design-system/release-notes/1.3.1.md":c,"../../packages/design-system/release-notes/1.3.2.md":l,"../../packages/design-system/release-notes/1.3.3.md":u,"../../packages/design-system/release-notes/1.3.4.md":d,"../../packages/markdown/release-notes/1.0.0.md":f,"../../packages/markdown/release-notes/1.1.0.md":p,"../../packages/markdown/release-notes/1.2.0.md":m,"../../packages/markdown/release-notes/1.2.1.md":h,"../../packages/markdown/release-notes/1.2.2.md":g,"../../packages/mcp/release-notes/0.1.0.md":_,"../../packages/styled-system/release-notes/5.2.0.md":v,"../../packages/styled-system/release-notes/5.3.0.md":y,"../../packages/styled-system/release-notes/5.4.0.md":b,"../../packages/styled-system/release-notes/5.5.0.md":x,"../../packages/styled-system/release-notes/5.6.0.md":S,"../../packages/styled-system/release-notes/5.6.1.md":C,"../../packages/styled-system/release-notes/5.7.0.md":w,"../../packages/styled-system/release-notes/5.7.1.md":T,"../../packages/styled-system/release-notes/5.8.0.md":E,"../../packages/styled-system/release-notes/5.8.1.md":D,"../../packages/styled-system/release-notes/5.8.2.md":O,"../../packages/styled-system/release-notes/5.8.3.md":k,"../../packages/ui-spec/release-notes/0.1.0.md":A}),N=e=>Object.entries(M).filter(([t])=>t.includes(`/${e}/release-notes/`)).map(([e,t])=>({version:e.split(`/`).pop().replace(/\.md$/,``),body:t})).sort((e,t)=>j(t.version,e.version)),P=t();function F({pkg:t}){return(0,P.jsxs)(n,{as:`section`,mt:5,children:[(0,P.jsx)(r,{variant:`h3`,as:`h2`,gutterBottom:!0,children:`Releases`}),N(t).map(({version:t,body:r})=>(0,P.jsx)(n,{mb:4,children:(0,P.jsx)(e,{children:r})},t))]})}export{F as t};